        type(row) is dict and set(row)=={"bytes","sha256"} and type(row["bytes"]) is int and
        0<row["bytes"]<=268435456 and valid_sha(row["sha256"]) for row in previous.values()),
        "PREVIOUS_SEVEN_EXECUTABLE_CONTENT_PINS_REQUIRED")
