 need(all(re.fullmatch('[1-9][0-9]{0,9}',word) and int(word)<=2147483647 for word in values),code)
 result=[int(word) for word in values]
 need(len(set(result))==len(result),'DIRECT_CHILDREN_DUPLICATE')
