  need(type(tid) is int and 0<tid<=2147483647 and type(children) is list,'THREAD_LIST_SCHEMA')
  values+=children
 need(len(values)<=MAX_CHILDREN,'DIRECT_CHILDREN_BOUND')
 need(len(set(values))==len(values),'DIRECT_CHILDREN_DUPLICATE')
